Summary:
[{
    "SDK_name": "IronSource",
    "API_name": "setMetaData",
    "conditions": [
      "The API should be executed before SDK initialization."
    ],
    "effects": [
      "This API manipulates user-level settings to comply with regional and demographic data privacy regulations.",
      "By setting the appropriate value to the function, developers can restrict sale or sharing of personal data, specify whether an application is directed at children or manage consent in compliance with GDPR."
    ],
    "parameter_configuations": [
      {
          "parameter_values":["do_not_sell", "true"],
          "conditions":["The user has opted out of 'sale' or 'sharing' of personal information."],
          "effects":["The sale or sharing of user's personal information is restricted."]
      },
      {
          "parameter_values":["do_not_sell", "false"],
          "conditions":["The 'sale' of personal information is permitted."],
          "effects":["The sale or sharing of user's personal information is allowed."]
      },
      {
          "parameter_values":["is_child_directed", "true"],
          "conditions":["The end-user is a child (as defined by applicable regulations."],
          "effects":["Specific end-users are flagged as children. This is especially useful for apps that are child-oriented or subject to COPPA regulations."]
      },
      {
          "parameter_values":["is_child_directed", "false"],
          "conditions":["The end-user is not a child."],
          "effects":["The application does not flag end-users as children."]
      },
      {
          "parameter_values":["is_deviceid_optout", "true"],
          "conditions":["Your app is directed at children or for apps that are directed at a mixed audience. Required for apps that need to prevent access to the Android Advertising ID (AAID) due to data privacy regulations."],
          "effects":["This prevents access to the AAID for end-users flagged as children, which is a requirement for certain apps (primarily children-oriented apps). Note that this can impact the app's monetization performance."]
      }
    ]
  }]
